/**
 * The Three resources behind Paper's R217.S05 grid.
 *
 * One group, one `LineSegments` per drawn level role. Paper's grid is overlay
 * ink with no depth test, drawn below the Paper sheet by render order. The mat's
 * grid is not line geometry: R217.S19 draws it per pixel in `stage-mat-grid.ts`.
 *
 * It owns no Camera, no pick root and no plan geometry: every position is
 * generated by `stage-grid` from the evaluation's own scale.
 */
import {
	BufferGeometry,
	Color,
	Float32BufferAttribute,
	Group,
	LineBasicMaterial,
	LineSegments
} from 'three';
import { STAGE_OVERLAY_LAYER } from '../paper-plan';
import { gridLinesFor, type GridPlan } from '../stage-grid';

export type GridSceneResources = {
	readonly group: Group;
	/** Update fade/role opacity without disposing the lattice. */
	update(plan: GridPlan): void;
	/** Paper's settle-in, 0 → 1, on top of each level's own opacity. */
	setFade(fade: number): void;
	dispose(): void;
};

/** Paper's grid inks sit just above the sheet. */
const PAPER_GRID_LIFT_METERS = 0.004;
/** Above Paper's room-floor tint (10), beneath every Plan ink role (20+). */
const PAPER_GRID_RENDER_ORDER = 15;

type Bucket = {
	readonly color: string;
	readonly opacity: number;
	readonly positions: number[];
};

export function createGridScene(plan: GridPlan): GridSceneResources {
	const group = new Group();
	group.name = 'StageGrid';
	const elevation = plan.datumMeters + PAPER_GRID_LIFT_METERS;
	const { rect } = plan;
	const buckets = new Map<string, Bucket>();

	for (const line of gridLinesFor(plan)) {
		// Keyed by role and colour, not opacity: a fade change updates this
		// material rather than generating a different bucket and geometry.
		const key = `${line.role}:${line.color}`;
		const bucket = buckets.get(key) ?? { color: line.color, opacity: line.opacity, positions: [] };
		if (line.axis === 'x') {
			bucket.positions.push(line.atMeters, elevation, rect.minZ, line.atMeters, elevation, rect.maxZ);
		} else {
			bucket.positions.push(rect.minX, elevation, line.atMeters, rect.maxX, elevation, line.atMeters);
		}
		buckets.set(key, bucket);
	}

	const disposables: { dispose(): void }[] = [];
	const materials = new Map<string, LineBasicMaterial>();
	const levelOpacity = new Map<LineBasicMaterial, number>();
	let settle = 1;
	const applyOpacity = (material: LineBasicMaterial, opacity: number): void => {
		levelOpacity.set(material, opacity);
		const next = opacity * settle;
		const transparent = next < 1;
		if (material.transparent !== transparent) material.needsUpdate = true;
		material.opacity = next;
		material.transparent = transparent;
	};
	for (const [bucketKey, bucket] of buckets) {
		if (bucket.positions.length === 0) continue;
		const geometry = new BufferGeometry();
		geometry.setAttribute('position', new Float32BufferAttribute(bucket.positions, 3));
		const material = new LineBasicMaterial({
			color: new Color(bucket.color).getHex(),
			transparent: bucket.opacity < 1,
			opacity: bucket.opacity,
			// PLATE inks are semantic colors; tone mapping would shift the calibrated
			// paper and mat values away from the shell's own tokens.
			toneMapped: false,
			depthTest: false,
			depthWrite: false
		});
		const object = new LineSegments(geometry, material);
		object.renderOrder = PAPER_GRID_RENDER_ORDER;
		// A Canvas-drawn overlay, never world geometry for a mask or appearance decision.
		object.layers.set(STAGE_OVERLAY_LAYER);
		object.frustumCulled = false;
		object.name = `StageGrid:${bucketKey}`;
		group.add(object);
		materials.set(bucketKey, material);
		levelOpacity.set(material, bucket.opacity);
		disposables.push(geometry, material);
	}

	return {
		group,
		update(plan) {
			// Geometry is keyed without opacity, so a zoom through the 8–16 px fade
			// reaches here instead of rebuilding the lattice. Roles are unchanged
			// within a geometry key; only their ink opacity differs.
			for (const level of plan.levels.levels) {
				const material = materials.get(`${level.role}:${level.color}`);
				if (material === undefined) continue;
				applyOpacity(material, level.opacity);
			}
		},
		setFade(fade) {
			settle = Math.min(1, Math.max(0, fade));
			for (const [material, opacity] of levelOpacity) applyOpacity(material, opacity);
		},
		dispose() {
			group.clear();
			materials.clear();
			levelOpacity.clear();
			for (const disposable of disposables) disposable.dispose();
		}
	};
}
